package net.civeira.phylax.features.access.userwebauthncredential.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class TransportsJsonVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property transports json of user webauthn credential ")
  void test_transports_json_v_o_builder() {
    Assertions.assertFalse(TransportsJsonVO.nullValue().getTransportsJson().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(TransportsJsonVO.tryFrom(null).getTransportsJson().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", TransportsJsonVO.from("one").getTransportsJson().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> TransportsJsonVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", TransportsJsonVO.from("one").toString());
  }
}
